{
  "passageId": "surface-tension-laplace",
  "items": [
    {
      "id": "R1",
      "type": "CAUSE",
      "otherName": "",
      "reason": "분자 간 인력으로 발생한 표면 장력이 방울을 구형으로 만드는 실제 작용을 설명하므로 인과 관계이다."
    },
    {
      "id": "R2",
      "type": "CAUSE",
      "otherName": "",
      "reason": "구형이라는 판단의 추론 근거가 아니라 구형을 실제로 만드는 표면 장력의 작용을 제시하므로 인과 관계이다."
    },
    {
      "id": "R3",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "같은 방울에 작용하는 압력들을 팽창과 수축이라는 반대 방향의 작용으로 비교하므로 대조이다."
    },
    {
      "id": "R4",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "방울에 작용하는 압력들의 관계를 라플라스 식과 비례 관계로 표현하므로 판별 기준 8의 식으로 나타내기에 해당한다."
    },
    {
      "id": "R5",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "내외부 압력 차이라는 동일한 기준에서 표면 장력과 반지름이 각각 정비례와 반비례 관계를 갖는다고 비교하므로 대조이다."
    },
    {
      "id": "R6",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "공기가 고압에서 저압으로 이동한다는 일반 원리를 폐포의 공기 출입 현상에 적용하므로 원리 적용이다."
    },
    {
      "id": "R7",
      "type": "CAUSE",
      "otherName": "",
      "reason": "분비된 계면 활성제가 액체층의 표면 장력을 실제로 낮추는 작용을 하므로 인과 관계이다."
    },
    {
      "id": "R8",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "폐포를 수축시키는 표면 장력의 작용에 대해 이를 낮추는 계면 활성제의 보완 작용을 제시하므로 문제·대응이다."
    },
    {
      "id": "R9",
      "type": "CAUSE",
      "otherName": "",
      "reason": "계면 활성제에 따른 표면 장력 감소가 폐포의 확장을 실제로 쉽게 하므로 인과 관계이다."
    },
    {
      "id": "R10",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "액체 방울의 압력과 표면 장력에 관한 라플라스 식을 폐포의 호흡 현상에 가져다 쓰므로 원리 적용이다."
    },
    {
      "id": "R11",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "액체 방울에서 표면 장력이 수축 압력으로 작용한다는 원리를 폐포의 액체층에 적용하므로 원리 적용이다."
    },
    {
      "id": "R12",
      "type": "CAUSE",
      "otherName": "",
      "reason": "두 기포 사이의 공기 이동이 더 큰 하나의 기포 형성으로 이어진다고 명시하므로 단순한 순서가 아닌 인과 관계이다."
    },
    {
      "id": "R13",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "라플라스 식을 크기가 다른 두 기포의 결합 현상을 이해하는 데 사용하므로 원리 적용이다."
    },
    {
      "id": "R14",
      "type": "PROCESS",
      "otherName": "",
      "reason": "노즐에서 잉크가 분사된 다음 공기 중에서 방울이 되는 단계의 차례를 제시하므로 과정·순서이다."
    },
    {
      "id": "R15",
      "type": "PROCESS",
      "otherName": "",
      "reason": "공기 중에서 잉크 방울이 형성된 뒤 종이에 도달하는 순서를 제시하므로 과정·순서이다."
    },
    {
      "id": "R16",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "앞서 제시한 라플라스 식을 구형 잉크 방울이라는 구체적 대상의 압력 관계에 적용하므로 원리 적용이다."
    },
    {
      "id": "R17",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "구형 잉크 방울이 형성되어 종이에 도달하더라도 그것만으로 제대로 된 인쇄가 보장되지는 않는다는 한계를 제시하므로 양보·한계이다."
    },
    {
      "id": "R18",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "잉크 방울 형성만으로는 부족하다는 지적에서 안정적인 도착 정도를 나타내는 지표로 논의를 옮기므로 전개·전환이다."
    },
    {
      "id": "R19",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "오네소르게 수의 여러 결정 요인 중 점도를 골라 그 의미를 자세히 설명하므로 구체화이다."
    },
    {
      "id": "R20",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "네 요인에 의해 결정된다는 설명을 점도 증가에 따른 오네소르게 수의 변화 방향으로 상세화하므로 구체화이다."
    },
    {
      "id": "R21",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "네 요인에 의해 결정된다는 설명을 표면 장력·밀도·노즐 지름의 곱과 맺는 관계로 상세화하므로 구체화이다."
    },
    {
      "id": "R22",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "오네소르게 수의 변화 방향이라는 같은 기준에서 점도 증가와 나머지 세 값의 곱의 증가가 반대 효과를 갖는다고 비교하므로 대조이다."
    },
    {
      "id": "R23",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "네 요인이 오네소르게 수를 결정하는 관계를 근거로 이들을 조절하면 안정적인 인쇄가 가능하다는 결론을 도출하므로 근거·도출이다."
    },
    {
      "id": "R24",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "안정적인 인쇄를 위한 적절한 조절을 오네소르게 수 0.1에서 1.0이라는 수치 범위로 자세히 제시하므로 구체화이다."
    },
    {
      "id": "R25",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "점도가 클수록 오네소르게 수가 커진다는 관계를 안정 범위 초과에 따른 잉크 미분사 사례로 보여 주므로 구체화·예시이다."
    },
    {
      "id": "R26",
      "type": "CONDITION",
      "otherName": "",
      "reason": "오네소르게 수가 안정 범위 안에 있는지 그보다 큰지에 따라 정상 인쇄와 미분사로 결과가 갈리므로 조건·분기이다."
    },
    {
      "id": "R27",
      "type": "CONDITION",
      "otherName": "",
      "reason": "오네소르게 수가 안정 범위보다 큰 경우와 작은 경우에 따라 미분사와 위성 방울 발생으로 결과가 갈리므로 조건·분기이다."
    },
    {
      "id": "R28",
      "type": "CAUSE",
      "otherName": "",
      "reason": "수많은 위성 잉크 방울의 발생이 원치 않는 오염을 실제로 일으키므로 인과 관계이다."
    },
    {
      "id": "R29",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "오네소르게 수가 동일한 네 요인에 의해 결정된다는 내용을 다시 말하므로 판별 기준 8의 재진술에 해당한다."
    },
    {
      "id": "R30",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "네 요인으로 결정된 오네소르게 수를 자료로 삼아 안정적인 인쇄 가능 정도를 판단하므로 근거·도출이다."
    },
    {
      "id": "R31",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "오네소르게 수의 범위별 인쇄 결과가 그 수로 인쇄 안정성을 판단할 수 있다는 결론을 뒷받침하므로 근거·도출이다."
    }
  ]
}

